INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'c6628fff-07fe-58fe-8b53-d298ac8aaea8', '5aa7c891-fff7-52e4-bfea-7d8810019077',
  'String `s` contains lowercase letters, digits, `(` and `)`, satisfying the following rules:

- Two digits cannot be adjacent.
- Two `(` cannot be adjacent.
- One `(` and one `)` cannot be adjacent.
- After any digit, there must be `(`.
- The quantities of `(` and `)` are equal.

Change string `s` until a new string `t` is created. `t` contains only lowercase letters. These are the changing rules:

- Substrings with the form `n(p)` can change to `pp...p` (`n` times `p`), where `n` is a digit and `p` is a string.
- If `p` still contains `(`, `)` or digits, continue to implement the above changing method.

Request: Implement function `expand(string s);` where `s` is a string with the above form; return the result as a string containing only lowercase letters.

Note: In this exercise, the libraries `iostream`, `string` and `using namespace std;` have been used. You can add other functions for your answer, but you are not allowed to add other libraries.', 7
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '2a436dc8-df6b-5b09-8941-09a445c70dab', '5aa7c891-fff7-52e4-bfea-7d8810019077',
  'Give a positive integer `x`, implement recursive function `void printHailstone(int number){}` to print the Hailstone Sequence of a given number up to 1 (no space at the end).

Hailstone Sequences follow these rules:

- If a number is even, divide it by 2.
- If a number is odd, multiply it by 3 and add 1.

Example: If `number = 5`, 5 is odd number so next number is $5*3 + 1 = 16$. 16 is even number so next number is $16/2 = 8$... Finally, we get Hailstone sequence: `5 16 8 4 2 1`.

You can find more information at: https://diendantoanhoc.net/topic/89145-d%C3%A3y-s%E1%BB%91-hailstone/.

Note: Please note that you can''t use the keywords `for`, `while`, or `goto` (even in variable names or comments). You can implement other recursive functions if needed. For this exercise, we have `#include <iostream>` and `using namespace std;`.', 8
);

