INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '29a457be-1ec9-540f-a69e-c1cdf8e763c7', '5aa7c891-fff7-52e4-bfea-7d8810019077',
  'There are $n$ people, each person has a number between 1 and 100000 ($1 \le n \le 100000$). Given a number target. Two people can be matched as a **perfect pair** if the sum of numbers they have is equal to target. A person can be matched no more than 1 time.

**Request:** Implement function:

```cpp
int pairMatching(vector<int>& nums, int target);
```

Where nums is the list of numbers of $n$ people, target is the given number. This function returns the number of perfect pairs that can be found from the list.

**Example:** The list of numbers is $\{1, 3, 5, 3, 7\}$ and target $= 6$. Therefore, the number of perfect pairs that can be found from the list is 2 (pair $(1, 5)$ and pair $(3, 3)$).

**Note:** In this exercise, the libraries iostream, string, cstring, climits, utility, vector, list, stack, queue, map, unordered_map, set, unordered_set, functional, algorithm have been included and namespace std is used. You can write helper functions and classes. Importing other libraries is allowed, but not encouraged, and may result in unexpected errors.', 65
);

COMMIT;
